public class JjFillTokenTests {

    @Test
    public void testFillTokenWithNullLiteralImage() {
        String input = "test";
        SimpleCharStream stream = new SimpleCharStream(new StringReader(input), 1, 1);
        XPathParserTokenManager tokenManager = new XPathParserTokenManager(stream);

        // Setup fields directly via reflection or by simulated parsing state setup
        // Since jjmatchedKind is protected and dependent on lex state, we simulate a token
        // type that is known to have a null image in jjstrLiteralImages.
        // Index 9 corresponds to literal "+" which has an image, let's find a null one.
        // Looking at the fields, index 0 is "", index 8 is "|".
        // Many nulls exist in the array (e.g., index 1, 2, 3, 4, 5, 9, 10, etc.).
        // We will simulate a match for index 1 (which is null in jjstrLiteralImages).

        tokenManager.jjmatchedKind = 1; 

        // We must ensure the stream returns the correct image for the token
        // SimpleCharStream.GetImage() relies on internal buffers (buf, bufpos, tokenBegin).
        // We manually set these to simulate the scanner having identified a token.

        // In SimpleCharStream: tokenBegin is the start index, bufpos is the current index.
        // We simulate that the scanner has read 4 characters "test".
        stream.beginToken();
        char[] buffer = (char[]) getPrivateField(stream, "buffer");
        int len = input.length();
        for (int i = 0; i < len; i++) {
            buffer[i] = input.charAt(i);
            stream.EndColumn++; 
            if (i > 0) stream.BeginColumn++;
        }
        setPrivateField(stream, "bufpos", len - 1);
        setPrivateField(stream, "tokenBegin", 0);

        // Mock Line/Column info
        setPrivateField(stream, "line", 2);
        setPrivateField(stream, "column", 10);
        setPrivateField(stream, "bufline", new int[]{1, 1, 1, 1});
        setPrivateField(stream, "bufcolumn", new int[]{0, 1, 2, 3});

        Token t = tokenManager.jjFillToken();

        assertNotNull(t);
        assertEquals(1, t.kind);
        assertEquals("test", t.image);
        assertEquals(1, t.beginLine);
        assertEquals(0, t.beginColumn);
        assertEquals(1, t.endLine);
        assertEquals(3, t.endColumn);
    }

    @Test
    public void testFillTokenWithDefinedLiteralImage() {
        String input = "//"; // Literal for "//"
        SimpleCharStream stream = new SimpleCharStream(new StringReader(input), 1, 1);
        XPathParserTokenManager tokenManager = new XPathParserTokenManager(stream);

        // Index 7 corresponds to "//" in jjstrLiteralImages
        tokenManager.jjmatchedKind = 7; 

        Token t = tokenManager.jjFillToken();

        assertNotNull(t);
        assertEquals(7, t.kind);
        // The image should come from jjstrLiteralImages, not the stream
        assertEquals("//", t.image); 
        assertEquals(1, t.beginLine);
        assertEquals(1, t.beginColumn);
        assertEquals(1, t.endLine);
        assertEquals(1, t.endColumn);
