import static org.junit.Assert.*;

import java.util.Locale;

import org.apache.commons.jxpath.ri.model.NodePointer;
import org.jdom.Attribute;
import org.jdom.Element;
import org.jdom.Text;
import org.junit.Before;
import org.junit.Test;

public class CompareChildNodePointersTests {

    private Element parentElement;
    private JDOMNodePointer parentPointer;

    @Before
    public void setUp() {
        parentElement = new Element("parent");
        parentPointer = new JDOMNodePointer(parentElement, Locale.US);
    }

    @Test
    public void testCompareSameNode() {
        Element child1 = new Element("child1");
        parentElement.addContent(child1);

        NodePointer pointer1 = new JDOMNodePointer(parentPointer, child1);
        NodePointer pointer2 = new JDOMNodePointer(parentPointer, child1);

        int result = parentPointer.compareChildNodePointers(pointer1, pointer2);
        assertEquals("Same nodes should compare to 0", 0, result);
    }

    @Test
    public void testCompareChildNodesOrder() {
        Element child1 = new Element("child1");
        Element child2 = new Element("child2");
        parentElement.addContent(child1);
        parentElement.addContent(child2);

        NodePointer pointer1 = new JDOMNodePointer(parentPointer, child1);
        NodePointer pointer2 = new JDOMNodePointer(parentPointer, child2);

        // child1 comes before child2
        int result1 = parentPointer.compareChildNodePointers(pointer1, pointer2);
        assertEquals("First child should be less than second", -1, result1);

        // reverse order comparison
        int result2 = parentPointer.compareChildNodePointers(pointer2, pointer1);
        assertEquals("Second child should be greater than first", 1, result2);
    }

    @Test
    public void testCompareAttributeBeforeElement() {
        Attribute attr = new Attribute("id", "1");
        Element child = new Element("child");
