    @Test
    public void testGetSuffixWithinBufferBounds() throws Exception {
        String content = "abcdefghijklmnopqrstuvwxyz";
        SimpleCharStream stream = new SimpleCharStream(new StringReader(content));
        stream.BeginToken(); // Fill buffer, bufpos moves to 0 ('a')
        // Move buffer position forward
        stream.readChar(); // bufpos 1 ('b')
        stream.readChar(); // bufpos 2 ('c')
        stream.readChar(); // bufpos 3 ('d')
        stream.readChar(); // bufpos 4 ('e')

        // Request suffix of length 2. Should return chars at indices 3, 4 ('d', 'e')
        // Logic: bufpos (4) + 1 = 5. len = 2. 5 >= 2 is true.
        // Copy from buffer[4 - 2 + 1] = buffer[3]
        char[] result = stream.GetSuffix(2);
        char[] expected = {'d', 'e'};
        assertArrayEquals(expected, result);
    }

    @Test
    public void testGetSuffixWrappingBuffer() throws Exception {
        // Create a small buffer to force expansion easily
        String content = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        // Buffer size 12
        SimpleCharStream stream = new SimpleCharStream(new StringReader(content), 1, 1, 12);

        // BeginToken reads '0' (index 0). 
        stream.BeginToken();

        // Read 15 more characters (indices 1..15).
        // This forces the buffer to expand (size 12 -> 24) after reading 'B'.
        // We will end up at 'F' (index 15).
        for (int i = 0; i < 15; i++) {
            stream.readChar();
        }

        // Current state:
        // bufpos is 15 (pointing to 'F').
        // Buffer size is 24.
        // We want suffix of length 5.
        // bufpos (15) + 1 = 16. len = 5. 16 >= 5 is true.
        // Copy from buffer[15 - 5 + 1] = buffer[11].
        // buffer[11] is 'B'.
        // Expected: 'B', 'C', 'D', 'E', 'F'.

        char[] result = stream.GetSuffix(5);
        char[] expected = {'B', 'C', 'D', 'E', 'F'};
