package org.apache.commons.jxpath.ri.axes;

import static org.junit.Assert.*;

import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.compiler.NodeNameTest;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.dom.DOMNodePointer;
import org.junit.Before;
import org.junit.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Element;

import javax.xml.parsers.DocumentBuilderFactory;

public class NextNodeTests {

    private Document document;
    private EvalContext parentContext;
    private Element contextNode;

    @Before
    public void setUp() throws Exception {
        document = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Element root = document.createElement("root");
        document.appendChild(root);

        // Preceding structure
        Element preceding = document.createElement("preceding");
        root.appendChild(preceding);
        Element precedingChild = document.createElement("precedingChild");
        preceding.appendChild(precedingChild);

        // Context structure
        Element contextParent = document.createElement("contextParent");
        root.appendChild(contextParent);
        contextNode = document.createElement("contextNode");
        contextParent.appendChild(contextNode);

        // Following structure
        Element following = document.createElement("following");
        root.appendChild(following);
        Element followingChild = document.createElement("followingChild");
        following.appendChild(followingChild);

        // Create a parent context that sets the current node to 'contextNode'
        NodePointer rootPtr = new DOMNodePointer(root, null, null);
        NodePointer contextParentPtr = rootPtr.childIterator(null, false, null).getNodePointer();
        // Find contextNode specifically
        NodeIterator childIter = contextParentPtr.childIterator(null, false, null);
        NodePointer contextPtr = null;
        while (childIter.setPosition(childIter.getPosition() + 1)) {
            NodePointer ptr = childIter.getNodePointer();
            if (ptr.getName().getName().equals("contextNode")) {
                contextPtr = ptr;
                break;
            }
        }

        final NodePointer currentPointer = contextPtr;
        parentContext = new EvalContext(null) {
            @Override
            public NodePointer getCurrentNodePointer() {
                return currentPointer;
            }

            @Override
            public boolean nextNode() {
                return false;
            }
        };
    }

    @Test
    public void testNextNodeFollowing() {
        // Navigate following logic (forward in document order from contextNode)
        // reverse = false
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("*")), false);

        // Document order expects 'following' parent first, then its child
        assertTrue(context.nextNode());
        assertEquals("following", context.getCurrentNodePointer().getName().getName());

        assertTrue(context.nextNode());
        assertEquals("followingChild", context.getCurrentNodePointer().getName().getName());

        assertFalse(context.nextNode());
    }

    @Test
    public void testNextNodePreceding() {
        // Navigate preceding logic (reverse in document order from contextNode)
        // reverse = true
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("*")), true);

        // Reverse document order expects 'preceding' child first, then its parent
        assertTrue(context.nextNode());
        assertEquals("precedingChild", context.getCurrentNodePointer().getName().getName());

        assertTrue(context.nextNode());
        assertEquals("preceding", context.getCurrentNodePointer().getName().getName());

        assertFalse(context.nextNode());
    }

    @Test
    public void testNextNodeWithFilter() {
        // Filter for only nodes named "following"
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("following")), false);

        assertTrue(context.nextNode());
        assertEquals("following", context.getCurrentNodePointer().getName().getName());

        assertFalse(context.nextNode());
    }

    @Test
    public void testNextNodeNoMatch() {
        // Filter for non-existent node name
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("nonexistent")), false);

        assertFalse(context.nextNode());
    }
}

package org.apache.commons.jxpath.ri.axes;

import static org.junit.Assert.*;

import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.compiler.NodeNameTest;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.dom.DOMNodePointer;
import org.junit.Before;
import org.junit.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Element;

import javax.xml.parsers.DocumentBuilderFactory;

public class NextNodeTests {

    private Document document;
    private EvalContext parentContext;
    private Element contextNode;
    private Element precedingNode;
    private Element followingNode;

    @Before
    public void setUp() throws Exception {
        document = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Element root = document.createElement("root");
        document.appendChild(root);

        // Structure:
        // <root>
        //   <preceding><p_child/></preceding>
        //   <context/>
        //   <following><f_child/></following>
        // </root>

        precedingNode = document.createElement("preceding");
        root.appendChild(precedingNode);
        Element pChild = document.createElement("p_child");
        precedingNode.appendChild(pChild);

        contextNode = document.createElement("context");
        root.appendChild(contextNode);

        followingNode = document.createElement("following");
        root.appendChild(followingNode);
        Element fChild = document.createElement("f_child");
        followingNode.appendChild(fChild);

        NodePointer rootPtr = new DOMNodePointer(root, null, null);
        NodePointer contextPtr = null;

        NodeIterator it = rootPtr.childIterator(null, false, null);
        while (it.setPosition(it.getPosition() + 1)) {
            NodePointer ptr = it.getNodePointer();
            if (ptr.getName().getName().equals("context")) {
                contextPtr = ptr;
                break;
            }
        }

        final NodePointer currentPointer = contextPtr;
        parentContext = new EvalContext(null) {
            @Override
            public NodePointer getCurrentNodePointer() {
                return currentPointer;
            }

            @Override
            public boolean nextNode() {
                return false;
            }
        };
    }

    @Test
    public void testNextNodeFollowing() {
        // reverse = false (Following axis)
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("*")), false);

        // 1. Should find 'following' (sibling of context)
        assertTrue(context.nextNode());
        assertEquals("following", context.getCurrentNodePointer().getName().getName());

        // 2. Should then find 'f_child' (child of following)
        assertTrue(context.nextNode());
        assertEquals("f_child", context.getCurrentNodePointer().getName().getName());

        // 3. No more nodes
        assertFalse(context.nextNode());
    }

    @Test
    public void testNextNodePreceding() {
        // reverse = true (Preceding axis)
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("*")), true);

        // 1. Preceding axis visits descendants of preceding nodes first (reverse document order).
        // So it should find 'p_child' (child of preceding)
        assertTrue(context.nextNode());
        assertEquals("p_child", context.getCurrentNodePointer().getName().getName());

        // 2. Then it should find 'preceding' itself
        assertTrue(context.nextNode());
        assertEquals("preceding", context.getCurrentNodePointer().getName().getName());

        // 3. No more nodes
        assertFalse(context.nextNode());
    }

    @Test
    public void testNextNodeWithFilter() {
        // Filter for only nodes named "following"
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("following")), false);

        assertTrue(context.nextNode());
        assertEquals("following", context.getCurrentNodePointer().getName().getName());

        // f_child does not match "following", should be skipped
        assertFalse(context.nextNode());
    }

    @Test
    public void testNextNodeNoMatch() {
        // Filter for non-existent node name
        PrecedingOrFollowingContext context = new PrecedingOrFollowingContext(parentContext, new NodeNameTest(new QName("nonexistent")), false);

        assertFalse(context.nextNode());
    }
}
